changeSet.sql:
-- ---- taxonomy_coverage_counts_384 CREATE FUNCTION nexus.taxonomy_coverage_counts_384(p_collection text) RETURNS TABLE(has_taxonomy boolean, chunks bigint, unassigned bigint) LANGUAGE sql STABLE AS $function$ WITH has_tax AS ( SELECT EXISTS ( SELECT 1 FROM nexus.taxonomy_centroids ct WHERE ct.collection = p_collection AND ct.embedding_384 IS NOT NULL ) AS v ), live AS MATERIALIZED ( SELECT c.tenant_id, c.chash FROM nexus.chunks c WHERE c.collection = p_collection AND c.embedding_384 IS NOT NULL AND (SELECT v FROM has_tax) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) ), total AS ( SELECT count(*) AS n FROM live ), unassigned_live AS ( SELECT count(*) AS n FROM live l WHERE NOT EXISTS ( SELECT 1 FROM nexus.topic_assignments ta JOIN nexus.topics t ON t.tenant_id = ta.tenant_id AND t.id = ta.topic_id WHERE ta.tenant_id = l.tenant_id AND ta.doc_id = l.chash AND t.collection = p_collection) ) SELECT (SELECT v FROM has_tax), (SELECT n FROM total), (SELECT n FROM unassigned_live) $function$;
REVOKE EXECUTE ON FUNCTION nexus.taxonomy_coverage_counts_384(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION nexus.taxonomy_coverage_counts_384(text) TO nexus_svc;
