DROP FUNCTION IF EXISTS nexus.taxonomy_coverage_counts_384(text);
DROP FUNCTION IF EXISTS nexus.taxonomy_coverage_counts_768(text);
DROP FUNCTION IF EXISTS nexus.taxonomy_coverage_counts_1024(text);
